const files = {
  "src/components/ThemeGesture.tsx": "\"use client\";\n\n// Two-finger gesture anywhere in the app:\n//   spread fingers apart (like zooming in)  → dark mode\n//   pinch fingers together (like zooming out) → light mode\n// A small moon/sun bubble follows the fingers so he can see what will happen before letting go.\n\nimport { useEffect, useState } from \"react\";\nimport { Moon, Sun } from \"lucide-react\";\nimport { pinchResult, setThemePref, type Theme } from \"@/lib/theme\";\nimport { useToast } from \"@/components/motion/Toast\";\n\ntype Hint = { x: number; y: number; theme: Theme | null; scale: number };\n\nconst dist = (t: TouchList) => Math.hypot(t[0].clientX - t[1].clientX, t[0].clientY - t[1].clientY);\nconst mid = (t: TouchList) => ({ x: (t[0].clientX + t[1].clientX) / 2, y: (t[0].clientY + t[1].clientY) / 2 });\n\nexport default function ThemeGesture() {\n  const [hint, setHint] = useState<Hint | null>(null);\n  const showToast = useToast();\n\n  useEffect(() => {\n    let start = 0;\n    let last: Hint | null = null;\n\n    const onStart = (e: TouchEvent) => {\n      if (e.touches.length !== 2 || document.querySelector(\"[role=dialog]\")) return;\n      start = dist(e.touches);\n      last = null;\n    };\n    const onMove = (e: TouchEvent) => {\n      if (!start || e.touches.length !== 2) return;\n      e.preventDefault(); // stop the browser zooming the page\n      const d = dist(e.touches);\n      const m = mid(e.touches);\n      last = { ...m, theme: pinchResult(start, d), scale: Math.min(Math.max(d / start, 0.5), 1.8) };\n      setHint(last);\n    };\n    const onEnd = (e: TouchEvent) => {\n      if (!start || e.touches.length > 0) return;\n      start = 0;\n      setHint(null);\n      if (last?.theme) {\n        const current = document.documentElement.dataset.theme === \"dark\" ? \"dark\" : \"light\";\n        setThemePref(last.theme, { x: last.x, y: last.y });\n        if (current !== last.theme) showToast(last.theme === \"dark\" ? \"Dark mode on\" : \"Light mode on\");\n      }\n    };\n    // iPhone Safari zoom gesture\n    const stopSafariZoom = (e: Event) => e.preventDefault();\n\n    window.addEventListener(\"touchstart\", onStart, { passive: true });\n    window.addEventListener(\"touchmove\", onMove, { passive: false });\n    window.addEventListener(\"touchend\", onEnd);\n    window.addEventListener(\"touchcancel\", onEnd);\n    document.addEventListener(\"gesturestart\", stopSafariZoom);\n    return () => {\n      window.removeEventListener(\"touchstart\", onStart);\n      window.removeEventListener(\"touchmove\", onMove);\n      window.removeEventListener(\"touchend\", onEnd);\n      window.removeEventListener(\"touchcancel\", onEnd);\n      document.removeEventListener(\"gesturestart\", stopSafariZoom);\n    };\n  }, [showToast]);\n\n  if (!hint) return null;\n  const dark = hint.theme === \"dark\";\n  const ready = hint.theme !== null;\n  return (\n    <div\n      aria-hidden\n      className=\"pointer-events-none fixed z-50 flex h-16 w-16 items-center justify-center rounded-full glass-bar\"\n      style={{ left: hint.x - 32, top: hint.y - 32, transform: `scale(${hint.scale})`, opacity: ready ? 1 : 0.6 }}\n    >\n      {hint.scale >= 1 ? <Moon size={26} className={dark ? \"text-forest\" : \"text-ink-soft\"} /> : <Sun size={26} className={ready ? \"text-forest\" : \"text-ink-soft\"} />}\n    </div>\n  );\n}\n",
  "src/lib/liquid.test.ts": "import { describe, expect, it } from \"vitest\";\nimport { isSettled, shapeFor, stepSpring, type SpringState } from \"./liquid\";\n\nfunction run(from: SpringState, target: number, seconds: number) {\n  let s = from;\n  const path: number[] = [];\n  for (let t = 0; t < seconds; t += 1 / 60) {\n    s = stepSpring(s, target, 1 / 60);\n    path.push(s.x);\n  }\n  return { s, path };\n}\n\ndescribe(\"liquid glass spring\", () => {\n  it(\"reaches the new tab and settles in under a second\", () => {\n    const { s } = run({ x: 0, v: 0 }, 1, 0.75);\n    expect(isSettled(s, 1)).toBe(true);\n  });\n  it(\"overshoots only a little (soft, not bouncy)\", () => {\n    const { path } = run({ x: 0, v: 0 }, 1, 1);\n    const peak = Math.max(...path);\n    expect(peak).toBeGreaterThan(1.005); // there is an overshoot\n    expect(peak).toBeLessThan(1.08); // but it's small\n  });\n  it(\"handles quick taps: changing target mid-way keeps moving smoothly (no jump back)\", () => {\n    const first = run({ x: 0, v: 0 }, 2, 0.08).s; // heading to Me\n    const next = stepSpring(first, 1, 1 / 60); // tapped Man instead\n    expect(next.x).toBeGreaterThanOrEqual(first.x); // momentum carries on, no reset to the start\n    expect(next.x - first.x).toBeLessThan(0.25); // one frame = a small, continuous step\n    expect(isSettled(run(next, 1, 0.8).s, 1)).toBe(true);\n  });\n  it(\"stays stable when the phone skips frames\", () => {\n    const s = stepSpring({ x: 0, v: 0 }, 1, 0.5);\n    expect(Number.isFinite(s.x)).toBe(true);\n    expect(s.x).toBeLessThan(1.2);\n  });\n});\n\ndescribe(\"glass shape\", () => {\n  it(\"is round at rest\", () => {\n    expect(shapeFor(0)).toEqual({ scaleX: 1, scaleY: 1, origin: \"center\", lean: 0 });\n  });\n  it(\"stretches while moving, keeps the back edge and reaches forward\", () => {\n    const right = shapeFor(4);\n    expect(right.scaleX).toBeGreaterThan(1.15);\n    expect(right.scaleY).toBeLessThan(1);\n    expect(right.origin).toBe(\"left\");\n    expect(shapeFor(-4).origin).toBe(\"right\");\n  });\n  it(\"never stretches too far, even when flung\", () => {\n    expect(shapeFor(100).scaleX).toBeLessThanOrEqual(1.3);\n  });\n});\n",
  "src/lib/liquid.ts": "// Physics for the Liquid Glass tab bubble. Pure functions (no screen code), so they're easy to test.\n// Positions are in \"tabs\": 0 = Social, 1 = Man, 2 = Me. Velocity is tabs per second.\n\nexport interface SpringState {\n  x: number; // where the glass is\n  v: number; // how fast it's moving\n}\n\n/** Spring tuned to feel quick with a small, soft overshoot (damping ratio ≈ 0.67). */\nexport const SPRING = { stiffness: 210, damping: 19.5 };\n\n/** Move the spring one frame towards `target`. Small time steps keep it stable on slow phones. */\nexport function stepSpring(s: SpringState, target: number, dt: number, p = SPRING): SpringState {\n  let { x, v } = s;\n  let left = Math.min(dt, 0.064); // never jump more than ~4 frames at once\n  while (left > 0) {\n    const h = Math.min(left, 1 / 240);\n    const a = p.stiffness * (target - x) - p.damping * v;\n    v += a * h;\n    x += v * h;\n    left -= h;\n  }\n  return { x, v };\n}\n\n/** Close enough to stop animating (saves battery). */\nexport function isSettled(s: SpringState, target: number): boolean {\n  return Math.abs(target - s.x) < 0.0015 && Math.abs(s.v) < 0.01;\n}\n\nexport interface GlassShape {\n  scaleX: number; // stretch along the movement\n  scaleY: number; // gets a little thinner while stretched (keeps its \"volume\")\n  origin: \"left\" | \"right\" | \"center\"; // the trailing edge stays put, the leading edge reaches ahead\n  lean: number; // -1…1: which side is the front, for the uneven corners and the moving shine\n}\n\n/** Shape of the glass for its current speed: round at rest, stretched while moving. */\nexport function shapeFor(v: number): GlassShape {\n  const speed = Math.abs(v);\n  const stretch = Math.min(speed * 0.075, 0.3);\n  const lean = Math.max(-1, Math.min(1, v / 3));\n  return {\n    scaleX: 1 + stretch,\n    scaleY: 1 - stretch * 0.38,\n    origin: speed < 0.05 ? \"center\" : v > 0 ? \"left\" : \"right\",\n    lean,\n  };\n}\n",
  "src/lib/theme.test.ts": "import { describe, expect, it } from \"vitest\";\nimport { pinchResult, resolve } from \"./theme\";\n\ndescribe(\"appearance\", () => {\n  it(\"auto follows the phone, light and dark are fixed\", () => {\n    expect(resolve(\"auto\", true)).toBe(\"dark\");\n    expect(resolve(\"auto\", false)).toBe(\"light\");\n    expect(resolve(\"light\", true)).toBe(\"light\");\n    expect(resolve(\"dark\", false)).toBe(\"dark\");\n  });\n  it(\"spreading two fingers apart turns dark on, pinching them together turns it off\", () => {\n    expect(pinchResult(100, 200)).toBe(\"dark\");\n    expect(pinchResult(200, 100)).toBe(\"light\");\n  });\n  it(\"ignores small or unclear movements\", () => {\n    expect(pinchResult(100, 120)).toBeNull();\n    expect(pinchResult(100, 85)).toBeNull();\n    expect(pinchResult(10, 200)).toBeNull();\n  });\n});\n",
  "src/lib/theme.ts": "\"use client\";\n\n// Light / dark appearance. \"auto\" follows the phone's own setting.\n// Saved on this phone as \"ms_theme\". The page reads it before it paints (see app/layout.tsx), so there's no flash.\n\nimport { useSyncExternalStore } from \"react\";\n\nexport type ThemePref = \"light\" | \"dark\" | \"auto\";\nexport type Theme = \"light\" | \"dark\";\n/** Colour modes. Green is Kayani's own colour and the default. */\nexport type Accent = \"green\" | \"blue\" | \"red\";\nexport const ACCENTS: { id: Accent; label: string; swatch: string }[] = [\n  { id: \"green\", label: \"Green\", swatch: \"#0f5c46\" },\n  { id: \"blue\", label: \"Blue\", swatch: \"#1e5bb8\" },\n  { id: \"red\", label: \"Red\", swatch: \"#b3263a\" },\n];\nconst ACCENT_KEY = \"ms_accent\";\n\nconst KEY = \"ms_theme\";\nconst listeners = new Set<() => void>();\nconst notify = () => listeners.forEach((l) => l());\n\nexport function readPref(): ThemePref {\n  try {\n    const v = localStorage.getItem(KEY);\n    return v === \"light\" || v === \"dark\" ? v : \"auto\";\n  } catch {\n    return \"auto\";\n  }\n}\n\nexport function resolve(pref: ThemePref, systemDark: boolean): Theme {\n  return pref === \"auto\" ? (systemDark ? \"dark\" : \"light\") : pref;\n}\n\nconst systemDark = () => typeof window !== \"undefined\" && window.matchMedia(\"(prefers-color-scheme: dark)\").matches;\n\nfunction apply(theme: Theme) {\n  const root = document.documentElement;\n  root.dataset.theme = theme;\n  root.style.colorScheme = theme;\n  syncBrowserBar();\n}\n\n/** The phone's top bar takes the app's colour. */\nfunction syncBrowserBar() {\n  const css = getComputedStyle(document.documentElement);\n  const dark = document.documentElement.dataset.theme === \"dark\";\n  const color = css.getPropertyValue(dark ? \"--a-bg-dark\" : \"--a-forest\").trim();\n  if (color) document.querySelector('meta[name=\"theme-color\"]')?.setAttribute(\"content\", color);\n}\n\nexport function readAccent(): Accent {\n  try {\n    const v = localStorage.getItem(ACCENT_KEY);\n    return v === \"blue\" || v === \"red\" ? v : \"green\";\n  } catch {\n    return \"green\";\n  }\n}\n\n/** Change the colour mode (Green, Blue, Red). Spreads in a circle from the tapped point, like the theme. */\nexport function setAccent(accent: Accent, from?: { x: number; y: number }) {\n  try {\n    if (accent === \"green\") localStorage.removeItem(ACCENT_KEY);\n    else localStorage.setItem(ACCENT_KEY, accent);\n  } catch {}\n  const change = () => {\n    if (accent === \"green\") delete document.documentElement.dataset.accent;\n    else document.documentElement.dataset.accent = accent;\n    syncBrowserBar();\n  };\n  withCircle(change, from);\n  notify();\n}\n\nexport function useAccent(): Accent {\n  return useSyncExternalStore(\n    (cb) => {\n      listeners.add(cb);\n      return () => listeners.delete(cb);\n    },\n    readAccent,\n    () => \"green\",\n  );\n}\n\n/** Runs a visual change inside a circular reveal from `from` (when the phone supports it). */\nfunction withCircle(change: () => void, from?: { x: number; y: number }) {\n  const doc = document as Document & { startViewTransition?: (cb: () => void) => { ready: Promise<void> } };\n  const reduce = window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n  if (!doc.startViewTransition || reduce) return change();\n  const x = from?.x ?? window.innerWidth / 2;\n  const y = from?.y ?? window.innerHeight / 2;\n  const r = Math.hypot(Math.max(x, window.innerWidth - x), Math.max(y, window.innerHeight - y));\n  doc\n    .startViewTransition(change)\n    .ready.then(() =>\n      document.documentElement.animate(\n        { clipPath: [`circle(0px at ${x}px ${y}px)`, `circle(${r}px at ${x}px ${y}px)`] },\n        { duration: 550, easing: \"cubic-bezier(0.2, 0.8, 0.2, 1)\", pseudoElement: \"::view-transition-new(root)\" },\n      ),\n    )\n    .catch(() => {});\n}\n\n/**\n * Change the appearance. With `from` (a point on screen), the new look spreads out in a circle\n * from that point, on phones that support it; otherwise it simply switches.\n */\nexport function setThemePref(pref: ThemePref, from?: { x: number; y: number }) {\n  try {\n    if (pref === \"auto\") localStorage.removeItem(KEY);\n    else localStorage.setItem(KEY, pref);\n  } catch {}\n  const next = resolve(pref, systemDark());\n  const current = document.documentElement.dataset.theme === \"dark\" ? \"dark\" : \"light\";\n  if (next === current) apply(next);\n  else withCircle(() => apply(next), from);\n  notify();\n}\n\n/** Keep \"auto\" in step when the phone switches between light and dark by itself. */\nif (typeof window !== \"undefined\") {\n  window.matchMedia(\"(prefers-color-scheme: dark)\").addEventListener(\"change\", () => {\n    if (readPref() === \"auto\") {\n      apply(resolve(\"auto\", systemDark()));\n      notify();\n    }\n  });\n}\n\nexport function useThemePref(): ThemePref {\n  return useSyncExternalStore(\n    (cb) => {\n      listeners.add(cb);\n      return () => listeners.delete(cb);\n    },\n    readPref,\n    () => \"auto\",\n  );\n}\n\n/** Pinch gesture: did the two fingers spread apart (→ dark) or come together (→ light)? */\nexport function pinchResult(startDistance: number, endDistance: number): Theme | null {\n  if (startDistance < 30) return null; // fingers started too close to measure\n  const ratio = endDistance / startDistance;\n  if (ratio > 1.4) return \"dark\";\n  if (ratio < 0.7) return \"light\";\n  return null;\n}\n",
  "src/lib/themeBoot.ts": "// Kept separate from theme.ts (a client file) so the server layout can put it in <head>.\n\nconst KEY = \"ms_theme\";\n\n/** Runs before the page paints (inline in <head>), so dark mode never flashes white. */\nexport const THEME_BOOT_SCRIPT = `(function(){try{var p=localStorage.getItem(\"${KEY}\");var d=p===\"dark\"||(p!==\"light\"&&matchMedia(\"(prefers-color-scheme: dark)\").matches);var t=d?\"dark\":\"light\";document.documentElement.dataset.theme=t;document.documentElement.style.colorScheme=t;var a=localStorage.getItem(\"ms_accent\");if(a===\"blue\"||a===\"red\")document.documentElement.dataset.accent=a;}catch(e){}})();`;\n",
  "src/app/(app)/layout.tsx": "import BottomNav from \"@/components/BottomNav\";\nimport TabPager from \"@/components/TabPager\";\nimport { ToastProvider } from \"@/components/motion/Toast\";\nimport AccountSync from \"@/components/account/AccountSync\";\nimport AccountInviteSheet from \"@/components/account/AccountInvite\";\nimport ThemeGesture from \"@/components/ThemeGesture\";\n\nexport default function AppLayout({ children }: { children: React.ReactNode }) {\n  return (\n    <ToastProvider>\n      <AccountSync />\n      <AccountInviteSheet />\n      <ThemeGesture />\n      {/* The three tabs live in the pager; other pages (children) open on top of it */}\n      <TabPager>{children}</TabPager>\n      <BottomNav />\n    </ToastProvider>\n  );\n}\n",
  "src/app/globals.css": "@import \"tailwindcss\";\n\n/* Brand tokens — Kayani Men's Social (Fernly-inspired: white, forest green, mint) */\n/* Colour modes: the \"a-\" values are the chosen colour (Green, Blue or Red, set on <html data-accent>). */\n:root {\n  /* Green (default) */\n  --a-forest: #0f5c46;\n  --a-deep: #073b2d;\n  --a-mint: #dff3ea;\n  --a-strong: #5dcaa5;\n  --a-deep-rgb: 7 59 45;\n  --a-mint-rgb: 223 243 234;\n  --a-strong-rgb: 93 202 165;\n  /* …and its night version */\n  --a-forest-dark: #17785b;\n  --a-deep-dark: #0a3328;\n  --a-bright: #6fd3ae;\n  --a-soft: #d6f3e7;\n  --a-tint-dark: #16382d;\n  --a-bg-dark: #0b1411;\n  --a-surface-dark: #131f1b;\n  --a-line-dark: #24342e;\n\n  --bg: #f4f6f4;\n  --surface: #ffffff;\n  --ink: #0f1f1a;\n  --ink-soft: #5b6b65;\n  --line: #e3e8e5;\n  --forest: var(--a-forest);\n  --forest-deep: var(--a-deep);\n  --mint: var(--a-mint);\n  --mint-strong: var(--a-strong);\n}\n[data-accent=\"blue\"] {\n  --a-forest: #1e5bb8;\n  --a-deep: #0c2a57;\n  --a-mint: #e2ecfb;\n  --a-strong: #5b9cf0;\n  --a-deep-rgb: 12 42 87;\n  --a-mint-rgb: 226 236 251;\n  --a-strong-rgb: 91 156 240;\n  --a-forest-dark: #2a6fd6;\n  --a-deep-dark: #0d2650;\n  --a-bright: #8ab8ff;\n  --a-soft: #dbe8ff;\n  --a-tint-dark: #172c4d;\n  --a-bg-dark: #0a0f17;\n  --a-surface-dark: #121a26;\n  --a-line-dark: #233046;\n  --bg: #f3f5f9;\n  --line: #e1e6ee;\n}\n[data-accent=\"red\"] {\n  --a-forest: #b3263a;\n  --a-deep: #5a0f1b;\n  --a-mint: #fbe4e7;\n  --a-strong: #f07686;\n  --a-deep-rgb: 90 15 27;\n  --a-mint-rgb: 251 228 231;\n  --a-strong-rgb: 240 118 134;\n  --a-forest-dark: #c8364b;\n  --a-deep-dark: #4a0f18;\n  --a-bright: #ff99a6;\n  --a-soft: #ffe0e4;\n  --a-tint-dark: #44181f;\n  --a-bg-dark: #140b0d;\n  --a-surface-dark: #1e1316;\n  --a-line-dark: #3a2328;\n  --bg: #f8f4f4;\n  --line: #ece3e4;\n}\n\n@theme inline {\n  --color-bg: var(--bg);\n  --color-surface: var(--surface);\n  --color-ink: var(--ink);\n  --color-ink-soft: var(--ink-soft);\n  --color-line: var(--line);\n  --color-forest: var(--forest);\n  --color-forest-deep: var(--forest-deep);\n  --color-mint: var(--mint);\n  --color-mint-strong: var(--mint-strong);\n  --font-sans: \"Plus Jakarta Sans Variable\", system-ui, sans-serif;\n}\n\nhtml {\n  scroll-behavior: smooth;\n}\n\nbody {\n  background: var(--bg);\n  color: var(--ink);\n  font-family: \"Plus Jakarta Sans Variable\", system-ui, sans-serif;\n  -webkit-tap-highlight-color: transparent;\n}\n\n/* Gentle entrance motion */\n@keyframes rise {\n  from { opacity: 0; transform: translateY(12px); }\n  to { opacity: 1; transform: translateY(0); }\n}\n.rise { animation: rise 0.5s cubic-bezier(0.2, 0.8, 0.2, 1) both; }\n.rise-2 { animation-delay: 0.08s; }\n.rise-3 { animation-delay: 0.16s; }\n.rise-4 { animation-delay: 0.24s; }\n\n/* ===== Motion kit (Fernly-style) ===== */\n\n/* 1. Page enter: whole page fades in */\n@keyframes page-in {\n  from { opacity: 0; }\n  to { opacity: 1; }\n}\n.page-enter { animation: page-in 0.35s ease-out both; }\n\n/* 1b. Stagger: each direct child rises in, one after another */\n.stagger > * { animation: rise 0.55s cubic-bezier(0.2, 0.8, 0.2, 1) both; }\n.stagger > *:nth-child(1) { animation-delay: 0.04s; }\n.stagger > *:nth-child(2) { animation-delay: 0.10s; }\n.stagger > *:nth-child(3) { animation-delay: 0.16s; }\n.stagger > *:nth-child(4) { animation-delay: 0.22s; }\n.stagger > *:nth-child(5) { animation-delay: 0.28s; }\n.stagger > *:nth-child(6) { animation-delay: 0.34s; }\n.stagger > *:nth-child(7) { animation-delay: 0.40s; }\n.stagger > *:nth-child(n + 8) { animation-delay: 0.46s; }\n\n/* 2. Bars grow upward */\n@keyframes grow-up {\n  from { transform: scaleY(0); }\n  to { transform: scaleY(1); }\n}\n.grow-bar {\n  transform-origin: bottom;\n  animation: grow-up 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) both;\n}\n\n/* 3. Toast pill: pops up from the bottom, then fades away */\n@keyframes toast-in {\n  from { opacity: 0; transform: translate(-50%, 16px) scale(0.96); }\n  to { opacity: 1; transform: translate(-50%, 0) scale(1); }\n}\n@keyframes toast-out {\n  from { opacity: 1; transform: translate(-50%, 0) scale(1); }\n  to { opacity: 0; transform: translate(-50%, 8px) scale(0.98); }\n}\n.toast-in { animation: toast-in 0.32s cubic-bezier(0.2, 0.8, 0.2, 1) both; }\n.toast-out { animation: toast-out 0.25s ease-in both; }\n\n/* 4. Popup sheet: background dims + blurs, card scales in */\n@keyframes backdrop-in {\n  from { opacity: 0; }\n  to { opacity: 1; }\n}\n@keyframes sheet-in {\n  from { opacity: 0; transform: translateY(16px) scale(0.97); }\n  to { opacity: 1; transform: translateY(0) scale(1); }\n}\n.backdrop-in { animation: backdrop-in 0.25s ease-out both; }\n.sheet-in { animation: sheet-in 0.35s cubic-bezier(0.2, 0.8, 0.2, 1) both; }\n\n/* 5. Points burst: \"+15\" floats up and fades when an activity is done */\n@keyframes float-up {\n  0% { opacity: 0; transform: translateY(4px) scale(0.9); }\n  20% { opacity: 1; transform: translateY(0) scale(1.05); }\n  100% { opacity: 0; transform: translateY(-28px) scale(1); }\n}\n.float-up { animation: float-up 0.9s ease-out both; pointer-events: none; }\n\n/* Hatched (striped) bar, like Fernly's empty days */\n.hatch {\n  background-image: repeating-linear-gradient(\n    -45deg,\n    var(--line) 0 2px,\n    transparent 2px 7px\n  );\n  box-shadow: inset 0 0 0 1px var(--line);\n}\n\n/* Respect phones set to \"reduce motion\" */\n@media (prefers-reduced-motion: reduce) {\n  .rise, .page-enter, .stagger > *, .grow-bar,\n  .toast-in, .toast-out, .backdrop-in, .sheet-in, .float-up { animation: none; }\n}\n\n/* ===== Tabs: sliding strip of tabs + liquid glass tab bar ===== */\n\n/* The strip: three full-screen tabs side by side. The phone's own scrolling moves it. */\n.tab-strip {\n  position: fixed;\n  inset: 0;\n  display: flex;\n  overflow-x: auto;\n  overflow-y: hidden;\n  scroll-snap-type: x mandatory;\n  overscroll-behavior-x: contain;\n  scrollbar-width: none;\n  scroll-behavior: auto;\n  transition: opacity 0.15s ease-out;\n}\n.tab-strip::-webkit-scrollbar { display: none; }\n/* Each tab scrolls up and down on its own, and remembers where it was */\n.tab-panel {\n  flex: 0 0 100%;\n  height: 100%;\n  overflow-x: hidden;\n  overflow-y: auto;\n  scroll-snap-align: start;\n  scroll-snap-stop: always;\n  overscroll-behavior-y: contain;\n}\n/* Card rows that scroll sideways stop at their ends instead of dragging the whole tab along */\n.tab-panel .overflow-x-auto { overscroll-behavior-x: contain; }\n\n/* Pages that open on top of a tab */\n.overlay-page {\n  position: fixed;\n  inset: 0;\n  z-index: 10;\n  overflow-y: auto;\n  background: var(--bg);\n  overscroll-behavior-y: contain;\n}\n@keyframes slide-from-right {\n  from { opacity: 0.6; transform: translateX(40%); }\n  to { opacity: 1; transform: translateX(0); }\n}\n.slide-from-right { animation: slide-from-right 0.34s cubic-bezier(0.2, 0.8, 0.2, 1) backwards; }\n\n/* Frosted glass bar: page shows through, blurred and a little brighter */\n.glass-bar {\n  background: linear-gradient(180deg, rgba(255, 255, 255, 0.62), rgba(255, 255, 255, 0.42));\n  -webkit-backdrop-filter: blur(22px) saturate(1.8);\n  backdrop-filter: blur(22px) saturate(1.8);\n  border: 1px solid rgba(255, 255, 255, 0.7);\n  box-shadow:\n    0 10px 30px rgb(var(--a-deep-rgb) / 0.16),\n    0 2px 6px rgb(var(--a-deep-rgb) / 0.06),\n    inset 0 1px 0 rgba(255, 255, 255, 0.9),\n    inset 0 -1px 0 rgb(var(--a-deep-rgb) / 0.04);\n}\n/* ===== Liquid Glass: the moving piece of glass in the tab bar ===== */\n.liquid-glass {\n  will-change: transform, border-radius;\n  /* a clearer, brighter piece of glass sitting on the frosted bar */\n  background:\n    radial-gradient(120% 90% at 50% 0%, rgba(255, 255, 255, 0.8), rgba(255, 255, 255, 0) 60%),\n    linear-gradient(180deg, rgba(250, 253, 251, 0.94), rgb(var(--a-mint-rgb) / 0.9));\n  -webkit-backdrop-filter: blur(3px) saturate(1.6) brightness(1.06);\n  backdrop-filter: blur(3px) saturate(1.6) brightness(1.06);\n  /* edge lighting: bright rim on top, soft coloured rims on the sides (like light bending at the edge) */\n  box-shadow:\n    inset 0 1px 0.5px rgba(255, 255, 255, 0.95),\n    inset 0 -1px 1px rgb(var(--a-deep-rgb) / 0.12),\n    inset 1.5px 0 1px rgba(150, 220, 255, 0.35),\n    inset -1.5px 0 1px rgba(160, 255, 210, 0.35),\n    inset 0 0 0 0.5px rgba(255, 255, 255, 0.6),\n    0 6px 18px rgb(var(--a-deep-rgb) / 0.16),\n    0 1px 3px rgb(var(--a-deep-rgb) / 0.10);\n}\n/* a highlight that slides across the glass while it moves */\n.liquid-shine {\n  background: linear-gradient(105deg, rgba(255, 255, 255, 0) 30%, rgba(255, 255, 255, 0.45) 48%, rgba(255, 255, 255, 0) 62%);\n  mix-blend-mode: soft-light;\n  opacity: 0.9;\n  transition: transform 0.12s linear;\n}\n[data-theme=\"dark\"] .liquid-glass {\n  background:\n    radial-gradient(120% 90% at 50% 0%, rgba(255, 255, 255, 0.14), rgba(255, 255, 255, 0) 60%),\n    linear-gradient(180deg, color-mix(in srgb, var(--a-tint-dark) 80%, white 12%), var(--a-tint-dark));\n  -webkit-backdrop-filter: blur(3px) saturate(1.5) brightness(1.15);\n  backdrop-filter: blur(3px) saturate(1.5) brightness(1.15);\n  box-shadow:\n    inset 0 1px 0.5px rgba(255, 255, 255, 0.28),\n    inset 0 -1px 1px rgba(0, 0, 0, 0.3),\n    inset 1.5px 0 1px rgba(120, 200, 255, 0.22),\n    inset -1.5px 0 1px rgba(120, 255, 200, 0.22),\n    inset 0 0 0 0.5px rgba(255, 255, 255, 0.14),\n    0 6px 18px rgba(0, 0, 0, 0.4);\n}\n[data-theme=\"dark\"] .liquid-shine { opacity: 0.5; }\n\n@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {\n  .glass-bar { background: rgba(255, 255, 255, 0.96); }\n}\n@media (prefers-reduced-motion: reduce) {\n  .slide-from-right { animation: none; }\n}\n\n/* ===== Dark mode ===== */\n/* Same brand, night version: deep green-black background, soft light text, mint accents. */\n[data-theme=\"dark\"] {\n  --bg: var(--a-bg-dark);\n  --surface: var(--a-surface-dark);\n  --ink: #e8eeeb;\n  --ink-soft: #9fb0a9;\n  --line: var(--a-line-dark);\n  --forest: var(--a-forest-dark);\n  --forest-deep: var(--a-deep-dark);\n  /* --mint stays light: it's used for light text on the dark green cards */\n}\n[data-theme=\"dark\"] body { background: var(--bg); }\n\n/* Light-tinted backgrounds become dark green tints */\n[data-theme=\"dark\"] .bg-mint { background-color: var(--a-tint-dark); }\n[data-theme=\"dark\"] .bg-mint\\/60 { background-color: color-mix(in srgb, var(--a-tint-dark) 78%, transparent); }\n[data-theme=\"dark\"] .bg-mint\\/50 { background-color: color-mix(in srgb, var(--a-tint-dark) 62%, transparent); }\n/* Green text becomes brighter so it reads on dark */\n[data-theme=\"dark\"] .text-forest { color: var(--a-bright); }\n[data-theme=\"dark\"] .text-forest-deep:not([class*=\"bg-white\"]) { color: var(--a-soft); }\n[data-theme=\"dark\"] .ring-forest { --tw-ring-color: var(--a-bright); }\n/* Warning and error boxes */\n[data-theme=\"dark\"] .bg-red-50 { background-color: rgba(185, 28, 28, 0.18); }\n[data-theme=\"dark\"] .text-red-700, [data-theme=\"dark\"] .text-red-800 { color: #fca5a5; }\n[data-theme=\"dark\"] .bg-amber-50 { background-color: rgba(180, 120, 20, 0.18); }\n[data-theme=\"dark\"] .text-amber-800, [data-theme=\"dark\"] .text-amber-900 { color: #fcd34d; }\n/* Popup background stays dark (ink turns light in dark mode) */\n[data-theme=\"dark\"] .bg-ink\\/30 { background-color: rgba(0, 0, 0, 0.55); }\n\n/* Dark glass tab bar */\n[data-theme=\"dark\"] .glass-bar {\n  background: linear-gradient(180deg, rgba(30, 46, 40, 0.66), rgba(19, 31, 27, 0.5));\n  border-color: rgba(255, 255, 255, 0.08);\n  box-shadow:\n    0 10px 30px rgba(0, 0, 0, 0.45),\n    inset 0 1px 0 rgba(255, 255, 255, 0.08);\n}\n@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {\n  [data-theme=\"dark\"] .glass-bar { background: rgba(19, 31, 27, 0.97); }\n}\n\n/* Switching themes: the new look grows out of a circle (set up in lib/theme.ts) */\n::view-transition-old(root),\n::view-transition-new(root) {\n  animation: none;\n  mix-blend-mode: normal;\n}\n\n/* Two-finger pinch is used for light/dark, so the app itself doesn't zoom */\n.tab-strip, .tab-panel, .overlay-page { touch-action: pan-x pan-y; }\n",
  "src/app/layout.tsx": "import type { Metadata, Viewport } from \"next\";\nimport \"@fontsource-variable/plus-jakarta-sans\";\nimport \"./globals.css\";\nimport { THEME_BOOT_SCRIPT } from \"@/lib/themeBoot\";\n\nexport const metadata: Metadata = {\n  title: \"Men's Social\",\n  description: \"Your private companion for men's wellness.\",\n  manifest: \"/manifest.webmanifest\",\n  appleWebApp: { capable: true, title: \"Men's Social\", statusBarStyle: \"default\" },\n};\n\nexport const viewport: Viewport = {\n  themeColor: \"#0f5c46\",\n  width: \"device-width\",\n  initialScale: 1,\n};\n\nexport default function RootLayout({\n  children,\n}: Readonly<{ children: React.ReactNode }>) {\n  return (\n    // suppressHydrationWarning: the theme script sets data-theme before React loads\n    <html lang=\"en\" suppressHydrationWarning>\n      <head>\n        <script dangerouslySetInnerHTML={{ __html: THEME_BOOT_SCRIPT }} />\n      </head>\n      <body className=\"antialiased\">{children}</body>\n    </html>\n  );\n}\n",
  "src/components/BottomNav.tsx": "\"use client\";\n\n// The tab bar, made of \"Liquid Glass\".\n// - A single piece of glass moves between tabs on a spring: it stretches in the direction it travels\n//   (front edge reaching ahead, back edge trailing), overshoots a little, then settles round.\n// - It follows the sliding strip of tabs, so during a swipe it moves exactly with the finger.\n// - Inside the glass, the icons are magnified and coloured, like a lens: the active tab lights up\n//   exactly where the glass is, even mid-move.\n// - Press the bar and the glass lifts; drag along the bar to scrub between tabs.\n// Everything moves by writing styles directly each frame, so React doesn't re-render while animating.\n\nimport { useEffect, useRef } from \"react\";\nimport Link from \"next/link\";\nimport { usePathname, useRouter } from \"next/navigation\";\nimport { MessageCircle, Sparkles, UserRound } from \"lucide-react\";\nimport { isTabRoot, stripPosition, TAB_PATHS, tabFor } from \"@/lib/tabs\";\nimport { isSettled, shapeFor, stepSpring, type SpringState } from \"@/lib/liquid\";\n\nconst tabs = [\n  { href: TAB_PATHS[0], label: \"Social\", Icon: MessageCircle },\n  { href: TAB_PATHS[1], label: \"Man\", Icon: Sparkles },\n  { href: TAB_PATHS[2], label: \"Me\", Icon: UserRound },\n];\nconst PAD = 6; // space between the bar's edge and the glass\n\nfunction TabFace({ Icon, label, active }: { Icon: (typeof tabs)[number][\"Icon\"]; label: string; active: boolean }) {\n  return (\n    <span className=\"flex flex-col items-center gap-0.5 py-2 text-[11px] font-semibold\">\n      <Icon size={21} strokeWidth={active ? 2.4 : 1.8} />\n      {label}\n    </span>\n  );\n}\n\nexport default function BottomNav() {\n  const pathname = usePathname();\n  const router = useRouter();\n  const active = tabFor(pathname);\n  const onRoot = isTabRoot(pathname);\n\n  const bar = useRef<HTMLDivElement>(null);\n  const glass = useRef<HTMLDivElement>(null);\n  const lens = useRef<HTMLDivElement>(null);\n  const shine = useRef<HTMLDivElement>(null);\n\n  // Animation state lives in refs (not React state) so it never causes re-renders\n  const spring = useRef<SpringState>({ x: Math.max(active, 0), v: 0 });\n  const lift = useRef({ x: 1, v: 0, target: 1 });\n  const target = useRef(Math.max(active, 0));\n  const raf = useRef(0);\n  const last = useRef(0);\n  const reduce = useRef(false);\n  const scrub = useRef<{ startX: number; moved: boolean; pointerId: number } | null>(null);\n  const suppressClick = useRef(false);\n\n  useEffect(() => {\n    reduce.current = window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n\n    const draw = () => {\n      const b = bar.current;\n      const g = glass.current;\n      if (!b || !g) return;\n      const cell = (b.clientWidth - PAD * 2) / tabs.length;\n      const s = spring.current;\n      const shape = reduce.current ? shapeFor(0) : shapeFor(s.v);\n      const l = lift.current.x;\n      const left = PAD + s.x * cell;\n\n      // The glass: position, stretch (from its speed) and lift (from pressing)\n      g.style.width = `${cell}px`;\n      g.style.transformOrigin = shape.origin === \"center\" ? \"50% 50%\" : `${shape.origin} 50%`;\n      g.style.transform = `translate3d(${left}px,0,0) scale(${shape.scaleX * l}, ${shape.scaleY * l})`;\n      // Uneven corners: the front edge is a little rounder and flatter, the back edge pulled out\n      const f = Math.abs(shape.lean);\n      const front = 26 + 6 * f;\n      const back = 26 - 6 * f;\n      g.style.borderRadius =\n        shape.lean >= 0\n          ? `${back}px ${front}px ${front}px ${back}px / ${26 + 2 * f}px ${26 - 3 * f}px ${26 - 3 * f}px ${26 + 2 * f}px`\n          : `${front}px ${back}px ${back}px ${front}px / ${26 - 3 * f}px ${26 + 2 * f}px ${26 + 2 * f}px ${26 - 3 * f}px`;\n\n      // The lens: the same icons, magnified and coloured, lined up with the real ones underneath\n      if (lens.current) {\n        // Lined up with the bar, then magnified around the glass centre (undoing the glass stretch,\n        // so the icons inside look slightly enlarged rather than squashed)\n        const c = left + cell / 2;\n        const mx = 1.12 / (shape.scaleX * l);\n        const my = 1.12 / (shape.scaleY * l);\n        lens.current.style.width = `${b.clientWidth}px`;\n        lens.current.style.transformOrigin = \"0 0\";\n        lens.current.style.transform = `translate3d(${-left}px,0,0) translate(${c}px,50%) scale(${mx},${my}) translate(${-c}px,-50%)`;\n      }\n      // The shine slides across the glass against the direction of travel\n      if (shine.current) shine.current.style.transform = `translateX(${-shape.lean * 18}%)`;\n    };\n\n    const tick = (now: number) => {\n      const dt = last.current ? (now - last.current) / 1000 : 1 / 60;\n      last.current = now;\n      if (reduce.current) {\n        spring.current = { x: target.current, v: 0 };\n      } else {\n        spring.current = stepSpring(spring.current, target.current, dt);\n        const L = lift.current; // a softer spring for the press \"lift\"\n        const a = 520 * (L.target - L.x) - 30 * L.v;\n        L.v += a * Math.min(dt, 0.05);\n        L.x += L.v * Math.min(dt, 0.05);\n      }\n      draw();\n      const resting = isSettled(spring.current, target.current) && Math.abs(lift.current.target - lift.current.x) < 0.001 && Math.abs(lift.current.v) < 0.01;\n      if (resting) {\n        spring.current = { x: target.current, v: 0 };\n        lift.current.x = lift.current.target;\n        draw();\n        raf.current = 0;\n        last.current = 0;\n      } else {\n        raf.current = requestAnimationFrame(tick);\n      }\n    };\n    const wake = () => {\n      if (!raf.current) raf.current = requestAnimationFrame(tick);\n    };\n\n    // While a finger swipes the pages, the glass follows the strip exactly.\n    // (Taps and scrubbing set the glass's destination directly, so it always moves on its own spring.)\n    const off = stripPosition.subscribe((pos, byFinger) => {\n      if (!byFinger || scrub.current?.moved) return;\n      target.current = pos;\n      wake();\n    });\n    draw(); // first paint: the glass already sits on the current tab (no glide on page load)\n\n    const onResize = () => draw();\n    window.addEventListener(\"resize\", onResize);\n    (bar.current as HTMLDivElement & { __wake?: () => void }).__wake = wake;\n    return () => {\n      off();\n      window.removeEventListener(\"resize\", onResize);\n      cancelAnimationFrame(raf.current);\n      raf.current = 0;\n    };\n  }, []);\n\n  // The tab changed (tap, end of a swipe, Back, or an article opened): the glass heads there\n  useEffect(() => {\n    if (active < 0 || scrub.current?.moved) return;\n    target.current = active;\n    (bar.current as (HTMLDivElement & { __wake?: () => void }) | null)?.__wake?.();\n  }, [active]);\n\n  const wakeBar = () => (bar.current as (HTMLDivElement & { __wake?: () => void }) | null)?.__wake?.();\n  const setLift = (on: boolean) => {\n    lift.current.target = on ? 1.07 : 1;\n    wakeBar();\n  };\n\n  // Drag along the bar to scrub through the tabs (the page follows), let go to land on the nearest one\n  const strip = () => document.querySelector<HTMLDivElement>(\".tab-strip\");\n  const posFromPointer = (clientX: number) => {\n    const b = bar.current!.getBoundingClientRect();\n    const cell = (b.width - PAD * 2) / tabs.length;\n    return Math.min(Math.max((clientX - b.left - PAD - cell / 2) / cell, 0), tabs.length - 1);\n  };\n  const onPointerDown = (e: React.PointerEvent) => {\n    setLift(true);\n    if (onRoot) scrub.current = { startX: e.clientX, moved: false, pointerId: e.pointerId };\n  };\n  const onPointerMove = (e: React.PointerEvent) => {\n    const sc = scrub.current;\n    const st = strip();\n    if (!sc || !st) return;\n    if (!sc.moved && Math.abs(e.clientX - sc.startX) < 8) return;\n    if (!sc.moved) {\n      sc.moved = true;\n      bar.current?.setPointerCapture(sc.pointerId);\n      st.style.scrollSnapType = \"none\";\n    }\n    const pos = posFromPointer(e.clientX);\n    st.scrollLeft = pos * st.clientWidth;\n    target.current = pos; // the glass sits under the finger\n    wakeBar();\n  };\n  const endPress = (e: React.PointerEvent) => {\n    setLift(false);\n    const sc = scrub.current;\n    scrub.current = null;\n    if (!sc?.moved) return;\n    const st = strip();\n    if (!st) return;\n    suppressClick.current = true; // the drag shouldn't also count as a tap on a tab\n    const landed = Math.round(posFromPointer(e.clientX));\n    target.current = landed;\n    wakeBar();\n    st.style.scrollSnapType = \"\";\n    st.scrollTo({ left: landed * st.clientWidth, behavior: \"smooth\" });\n    if (TAB_PATHS[landed] !== pathname) router.replace(TAB_PATHS[landed], { scroll: false });\n  };\n\n  return (\n    <nav aria-label=\"Main\" className=\"fixed inset-x-0 bottom-0 z-30 px-4 pb-[max(12px,env(safe-area-inset-bottom))]\">\n      <div\n        ref={bar}\n        className=\"glass-bar relative mx-auto max-w-sm touch-none select-none rounded-[32px]\"\n        onPointerDown={onPointerDown}\n        onPointerMove={onPointerMove}\n        onPointerUp={endPress}\n        onPointerCancel={endPress}\n        onPointerLeave={(e) => scrub.current?.moved || endPress(e)}\n      >\n        {/* The tabs (the real, clickable links) */}\n        <ul className=\"relative grid grid-cols-3 p-1.5\">\n          {tabs.map(({ href, label, Icon }, i) => {\n            const on = i === active;\n            return (\n              <li key={href}>\n                <Link\n                  href={href}\n                  replace={onRoot}\n                  scroll={false}\n                  draggable={false}\n                  aria-current={on ? \"page\" : undefined}\n                  onClick={(e) => {\n                    if (!suppressClick.current && !on) {\n                      target.current = i; // start the glass moving right away\n                      wakeBar();\n                    }\n                    if (suppressClick.current) {\n                      suppressClick.current = false;\n                      e.preventDefault();\n                      return;\n                    }\n                    // Tapping the tab you're already on scrolls it back to the top\n                    if (on && onRoot) {\n                      e.preventDefault();\n                      document.getElementById(`tab-panel-${i}`)?.scrollTo({ top: 0, behavior: \"smooth\" });\n                    }\n                  }}\n                  className=\"block rounded-[24px] text-ink-soft\"\n                >\n                  <TabFace Icon={Icon} label={label} active={false} />\n                </Link>\n              </li>\n            );\n          })}\n        </ul>\n\n        {/* The moving piece of glass, with a magnified, coloured copy of the icons inside (the lens) */}\n        {active >= 0 && (\n          <div ref={glass} aria-hidden className=\"liquid-glass pointer-events-none absolute left-0 top-1.5 bottom-1.5 overflow-hidden\">\n            <div ref={lens} className=\"absolute inset-y-0 left-0 will-change-transform\">\n              <div className=\"grid h-full grid-cols-3 px-1.5 text-forest-deep\">\n                {tabs.map(({ href, label, Icon }) => (\n                  <TabFace key={href} Icon={Icon} label={label} active />\n                ))}\n              </div>\n            </div>\n            <div ref={shine} className=\"liquid-shine absolute inset-0\" />\n          </div>\n        )}\n      </div>\n    </nav>\n  );\n}\n",
  "src/components/TabPager.tsx": "\"use client\";\n\n// The three main tabs side by side in one sliding strip, like a phone app.\n// - Swiping uses the phone's own scrolling (momentum + snap), so the page moves exactly with the finger\n//   and the next tab slides in beside it.\n// - All three tabs stay open in the background: no reloads, and each keeps its scroll position.\n// - The address (/social, /man, /me) follows the tab you land on.\n// - Other pages (an article, sign-up…) open on top of the strip and slide in from the right.\n\nimport { Component, useCallback, useEffect, useLayoutEffect, useRef, useState } from \"react\";\nimport { usePathname, useRouter } from \"next/navigation\";\nimport SocialTab from \"@/components/tabs/SocialTab\";\nimport ManTab from \"@/components/tabs/ManTab\";\nimport MeTab from \"@/components/tabs/MeTab\";\nimport { isTabRoot, stripPosition, TAB_PATHS, tabFor } from \"@/lib/tabs\";\nimport LockedTab from \"@/components/account/LockedTab\";\nimport { useAccount } from \"@/lib/account/useAccount\";\n\nconst PANELS = [SocialTab, ManTab, MeTab];\n\n/** Tells the Liquid Glass tab bar where the strip is (0 = Social … 2 = Me). */\nconst setBubble = (position: number, byFinger = false) =>\n  stripPosition.set(Math.min(Math.max(position, 0), TAB_PATHS.length - 1), byFinger);\n\nexport default function TabPager({ children }: { children: React.ReactNode }) {\n  const pathname = usePathname();\n  const router = useRouter();\n  const strip = useRef<HTMLDivElement>(null);\n  const onRoot = isTabRoot(pathname);\n  const tab = tabFor(pathname);\n  const [placed, setPlaced] = useState(false);\n  const settleTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  const frame = useRef(0);\n  // Is a finger moving the pages (or did one just let go and the page is still gliding)?\n  const fingerUntil = useRef(0);\n  // Man and Me hold his private records: guests see a locked preview instead\n  const acc = useAccount();\n  const locked = acc.status === \"guest\";\n\n  // Put the strip on the right tab: instantly on first load, smoothly when a tab is tapped\n  useLayoutEffect(() => {\n    const el = strip.current;\n    if (!el || tab < 0) return;\n    const target = tab * el.clientWidth;\n    if (Math.abs(el.scrollLeft - target) > 1) {\n      el.scrollTo({ left: target, behavior: placed ? \"smooth\" : \"instant\" });\n    }\n    if (!placed) {\n      setBubble(tab);\n      setPlaced(true);\n    }\n  }, [tab, placed]);\n\n  // Inside an article etc., the bubble rests on that page's tab\n  useEffect(() => {\n    if (!onRoot && tab >= 0) setBubble(tab);\n  }, [onRoot, tab]);\n\n  // Turning the phone or resizing the window: stay on the same tab\n  useEffect(() => {\n    const onResize = () => {\n      const el = strip.current;\n      if (el && tab >= 0) el.scrollTo({ left: tab * el.clientWidth, behavior: \"instant\" });\n    };\n    window.addEventListener(\"resize\", onResize);\n    return () => window.removeEventListener(\"resize\", onResize);\n  }, [tab]);\n\n  const onScroll = useCallback(() => {\n    const el = strip.current;\n    if (!el) return;\n    cancelAnimationFrame(frame.current);\n    frame.current = requestAnimationFrame(() =>\n      setBubble(el.scrollLeft / el.clientWidth, performance.now() < fingerUntil.current),\n    );\n    // When the strip comes to rest on another tab, update the address (without adding to Back history)\n    if (settleTimer.current) clearTimeout(settleTimer.current);\n    settleTimer.current = setTimeout(() => {\n      const landed = Math.round(el.scrollLeft / el.clientWidth);\n      if (isTabRoot(window.location.pathname) && TAB_PATHS[landed] !== window.location.pathname) {\n        router.replace(TAB_PATHS[landed], { scroll: false });\n      }\n    }, 90);\n  }, [router]);\n\n  return (\n    <>\n      <div\n        ref={strip}\n        onScroll={onScroll}\n        onTouchStart={() => (fingerUntil.current = Infinity)}\n        onTouchEnd={() => (fingerUntil.current = performance.now() + 700)}\n        onTouchCancel={() => (fingerUntil.current = performance.now() + 700)}\n        className={`tab-strip ${placed ? \"opacity-100\" : \"opacity-0\"}`}\n        inert={!onRoot}\n        aria-hidden={!onRoot}\n      >\n        {PANELS.map((Panel, i) => (\n          <section\n            key={TAB_PATHS[i]}\n            id={`tab-panel-${i}`}\n            className=\"tab-panel\"\n            aria-label={[\"Social\", \"Man\", \"Me\"][i]}\n            aria-hidden={onRoot && i !== tab ? true : undefined}\n          >\n            <div className=\"mx-auto max-w-md px-5 pb-32 pt-6\">\n              <PanelBoundary>\n                {i > 0 && acc.status === \"loading\" ? (\n                  <div className=\"h-64 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />\n                ) : i > 0 && locked ? (\n                  <LockedTab tab={i === 1 ? \"man\" : \"me\"} />\n                ) : (\n                  <Panel />\n                )}\n              </PanelBoundary>\n            </div>\n          </section>\n        ))}\n      </div>\n\n      {!onRoot && (\n        <div className=\"overlay-page\" id=\"overlay-page\">\n          <div className=\"mx-auto max-w-md px-5 pb-32 pt-6\">{children}</div>\n        </div>\n      )}\n    </>\n  );\n}\n\n/** If one tab crashes, the other two keep working. */\nclass PanelBoundary extends Component<{ children: React.ReactNode }, { failed: boolean }> {\n  state = { failed: false };\n  static getDerivedStateFromError() {\n    return { failed: true };\n  }\n  render() {\n    if (!this.state.failed) return this.props.children;\n    return (\n      <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n        <p className=\"font-semibold\">Something went wrong here</p>\n        <button onClick={() => location.reload()} className=\"mt-4 rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n          Reload\n        </button>\n      </div>\n    );\n  }\n}\n",
  "src/components/me/SettingsSections.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport Link from \"next/link\";\nimport { ChevronRight, Download, Droplet, EyeOff, Globe, Moon, MoonStar, ShieldCheck, Stethoscope, Trash2 } from \"lucide-react\";\nimport { ACCENTS, setAccent, setThemePref, useAccent, useThemePref, type ThemePref } from \"@/lib/theme\";\nimport Sheet from \"@/components/motion/Sheet\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport InterestsSheet from \"@/components/social/InterestsSheet\";\nimport { TOPICS } from \"@/lib/content/library\";\nimport type { TopicId } from \"@/lib/content/types\";\nimport { feedStore } from \"@/lib/feed/store\";\nimport { deleteMyData, exportMyData } from \"@/lib/me/data\";\nimport { setLang, type Lang } from \"@/lib/me/lang\";\nimport { progressStore } from \"@/lib/progress/store\";\nimport AccountCard from \"@/components/account/AccountCard\";\nimport type { AccountState } from \"@/lib/account/useAccount\";\nimport { deleteCloudData, stopSync } from \"@/lib/account/sync\";\n\n/* ───────── Goals and topics ───────── */\nexport function GoalsCard({ water, sleep, interests }: { water: number | null; sleep: number | null; interests: TopicId[] }) {\n  const showToast = useToast();\n  const [edit, setEdit] = useState<\"water\" | \"sleep\" | null>(null);\n  const [value, setValue] = useState(0);\n  const [topics, setTopics] = useState(false);\n\n  const open = (m: \"water\" | \"sleep\") => {\n    setValue(m === \"water\" ? (water ?? 2500) : (sleep ?? 420));\n    setEdit(m);\n  };\n  const step = edit === \"water\" ? 250 : 30;\n  const [min, max] = edit === \"water\" ? [500, 5000] : [240, 720];\n  const fmt = (m: \"water\" | \"sleep\", v: number) => (m === \"water\" ? `${(v / 1000).toFixed(v % 1000 ? 2 : 1).replace(/0$/, \"\")} L` : `${Math.floor(v / 60)}h${v % 60 ? ` ${v % 60}m` : \"\"}`);\n\n  function save() {\n    if (!edit) return;\n    progressStore.setGoal(edit, value, edit === \"water\" ? \"ml\" : \"min\");\n    showToast(`${edit === \"water\" ? \"Water\" : \"Sleep\"} goal: ${fmt(edit, value)}`);\n    setEdit(null);\n  }\n\n  return (\n    <section className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n      <h2 className=\"text-lg font-bold\">My goals</h2>\n      <div className=\"mt-3 grid grid-cols-2 gap-3\">\n        <button onClick={() => open(\"water\")} className=\"rounded-2xl bg-bg p-4 text-left ring-1 ring-line\">\n          <Droplet size={18} className=\"text-forest\" />\n          <p className=\"mt-2 text-xl font-bold\">{water ? fmt(\"water\", water) : \"Not set\"}</p>\n          <p className=\"text-xs text-ink-soft\">water a day</p>\n        </button>\n        <button onClick={() => open(\"sleep\")} className=\"rounded-2xl bg-bg p-4 text-left ring-1 ring-line\">\n          <Moon size={18} className=\"text-forest\" />\n          <p className=\"mt-2 text-xl font-bold\">{sleep ? fmt(\"sleep\", sleep) : \"Not set\"}</p>\n          <p className=\"text-xs text-ink-soft\">sleep a night</p>\n        </button>\n      </div>\n\n      <button onClick={() => setTopics(true)} className=\"mt-3 flex w-full items-center justify-between rounded-2xl bg-mint/60 px-4 py-3 text-left\">\n        <span className=\"min-w-0\">\n          <span className=\"block text-sm font-semibold text-forest-deep\">Topics I follow</span>\n          <span className=\"block truncate text-xs text-forest\">\n            {interests.length ? TOPICS.filter((t) => interests.includes(t.id)).map((t) => t.short).join(\" · \") : \"None yet. Choose what matters to you.\"}\n          </span>\n        </span>\n        <ChevronRight size={18} className=\"shrink-0 text-forest\" />\n      </button>\n\n      <Sheet open={edit !== null} onClose={() => setEdit(null)} title={edit === \"water\" ? \"Daily water goal\" : \"Nightly sleep goal\"}>\n        {edit && (\n          <>\n            <div className=\"flex items-center justify-between gap-3\">\n              <button aria-label=\"Less\" onClick={() => setValue((v) => Math.max(min, v - step))} className=\"h-12 w-12 rounded-full bg-bg text-2xl font-bold ring-1 ring-line\">\n                −\n              </button>\n              <p className=\"text-3xl font-bold\" aria-live=\"polite\">\n                {fmt(edit, value)}\n              </p>\n              <button aria-label=\"More\" onClick={() => setValue((v) => Math.min(max, v + step))} className=\"h-12 w-12 rounded-full bg-bg text-2xl font-bold ring-1 ring-line\">\n                +\n              </button>\n            </div>\n            <p className=\"mt-3 text-xs text-ink-soft\">\n              {edit === \"water\"\n                ? \"Most men do well with about 2 to 3 litres a day, more in heat or after exercise.\"\n                : \"Most adults need 7 to 9 hours. Pick a goal you can really keep.\"}\n            </p>\n            <button onClick={save} className=\"mt-4 w-full rounded-full bg-forest py-3 text-sm font-semibold text-white\">\n              Save goal\n            </button>\n          </>\n        )}\n      </Sheet>\n      <InterestsSheet open={topics} onClose={() => setTopics(false)} current={interests} />\n    </section>\n  );\n}\n\n/* ───────── App settings ───────── */\nexport function SettingsCard({ lang, discreet }: { lang: Lang; discreet: boolean }) {\n  const showToast = useToast();\n  const theme = useThemePref();\n  const accent = useAccent();\n  return (\n    <section className=\"divide-y divide-line rounded-3xl bg-surface ring-1 ring-line\">\n      <div className=\"p-5\">\n        <div className=\"flex items-center gap-3\">\n          <MoonStar size={18} className=\"shrink-0 text-forest\" />\n          <div className=\"min-w-0 flex-1\">\n            <p className=\"font-semibold\">Appearance</p>\n            <p className=\"text-xs text-ink-soft\">Tip: spread two fingers apart for dark, pinch them together for light.</p>\n          </div>\n        </div>\n        <div className=\"mt-3 grid grid-cols-3 rounded-full bg-bg p-1 text-xs font-semibold ring-1 ring-line\" role=\"radiogroup\" aria-label=\"Appearance\">\n          {([\"light\", \"dark\", \"auto\"] as ThemePref[]).map((t) => (\n            <button\n              key={t}\n              role=\"radio\"\n              aria-checked={theme === t}\n              onClick={(e) => setThemePref(t, { x: e.clientX, y: e.clientY })}\n              className={`rounded-full py-2 ${theme === t ? \"bg-forest text-white\" : \"text-ink-soft\"}`}\n            >\n              {t === \"light\" ? \"Light\" : t === \"dark\" ? \"Dark\" : \"Auto\"}\n            </button>\n          ))}\n        </div>\n        <p className=\"mt-4 text-xs font-semibold text-ink-soft\">Colour</p>\n        <div className=\"mt-2 flex gap-3\" role=\"radiogroup\" aria-label=\"Colour\">\n          {ACCENTS.map((a) => (\n            <button\n              key={a.id}\n              role=\"radio\"\n              aria-checked={accent === a.id}\n              onClick={(e) => {\n                setAccent(a.id, { x: e.clientX, y: e.clientY });\n                showToast(`${a.label} colour`);\n              }}\n              className={`flex flex-1 flex-col items-center gap-1.5 rounded-2xl py-2.5 text-xs font-semibold ring-1 transition-colors ${\n                accent === a.id ? \"bg-bg text-ink ring-forest\" : \"text-ink-soft ring-line\"\n              }`}\n            >\n              <span\n                className=\"flex h-8 w-8 items-center justify-center rounded-full shadow-inner\"\n                style={{ background: `linear-gradient(135deg, ${a.swatch}, ${a.swatch}cc)` }}\n              >\n                {accent === a.id && <span className=\"h-2.5 w-2.5 rounded-full bg-white\" />}\n              </span>\n              {a.label}\n            </button>\n          ))}\n        </div>\n      </div>\n      <div className=\"flex items-center gap-3 p-5\">\n        <Globe size={18} className=\"shrink-0 text-forest\" />\n        <div className=\"min-w-0 flex-1\">\n          <p className=\"font-semibold\">Language</p>\n          <p className=\"text-xs text-ink-soft\">Guides open in this language when there&apos;s a Kiswahili version.</p>\n        </div>\n        <div className=\"inline-flex shrink-0 rounded-full bg-bg p-1 text-xs font-semibold ring-1 ring-line\" role=\"radiogroup\" aria-label=\"Language\">\n          {([\"en\", \"sw\"] as const).map((l) => (\n            <button\n              key={l}\n              role=\"radio\"\n              aria-checked={lang === l}\n              onClick={() => {\n                setLang(l);\n                showToast(l === \"sw\" ? \"Kiswahili imechaguliwa\" : \"English selected\");\n              }}\n              className={`rounded-full px-3 py-1.5 ${lang === l ? \"bg-forest text-white\" : \"text-ink-soft\"}`}\n            >\n              {l === \"en\" ? \"EN\" : \"SW\"}\n            </button>\n          ))}\n        </div>\n      </div>\n\n      <label className=\"flex cursor-pointer items-center gap-3 p-5\">\n        <EyeOff size={18} className=\"shrink-0 text-forest\" />\n        <span className=\"min-w-0 flex-1\">\n          <span className=\"block font-semibold\">Discreet mode</span>\n          <span className=\"block text-xs text-ink-soft\">\n            Uses neutral wording on the Man tab, so private topics don&apos;t show if someone looks at your screen.\n          </span>\n        </span>\n        <input\n          type=\"checkbox\"\n          role=\"switch\"\n          checked={discreet}\n          onChange={(e) => {\n            feedStore.setDiscreet(e.target.checked);\n            showToast(e.target.checked ? \"Discreet mode on\" : \"Discreet mode off\");\n          }}\n          className=\"peer sr-only\"\n        />\n        <span\n          aria-hidden\n          className=\"relative h-7 w-12 shrink-0 rounded-full bg-line transition-colors peer-checked:bg-forest peer-focus-visible:ring-2 peer-focus-visible:ring-forest after:absolute after:left-1 after:top-1 after:h-5 after:w-5 after:rounded-full after:bg-white after:shadow after:transition-transform peer-checked:after:translate-x-5\"\n        />\n      </label>\n    </section>\n  );\n}\n\n/* ───────── Account, privacy and help ───────── */\nexport function PrivacyCard({ acc }: { acc: AccountState }) {\n  const signedIn = acc.status === \"signedIn\";\n  const showToast = useToast();\n  const [confirm, setConfirm] = useState(false);\n\n  function download() {\n    try {\n      const data = exportMyData(localStorage);\n      const blob = new Blob([JSON.stringify(data, null, 2)], { type: \"application/json\" });\n      const url = URL.createObjectURL(blob);\n      const a = document.createElement(\"a\");\n      a.href = url;\n      a.download = `mens-social-my-data-${new Date().toISOString().slice(0, 10)}.json`;\n      a.click();\n      setTimeout(() => URL.revokeObjectURL(url), 1000);\n      showToast(\"Your data is downloading\");\n    } catch {\n      showToast(\"Couldn't download on this browser\");\n    }\n  }\n\n  async function removeAll() {\n    if (signedIn) {\n      stopSync({ clearPhone: false });\n      try {\n        await deleteCloudData(acc.user.id);\n      } catch {\n        showToast(\"Couldn't delete from your account. Check your internet.\");\n        return;\n      }\n    }\n    try {\n      deleteMyData(localStorage);\n    } catch {}\n    // Reload so every screen starts fresh\n    window.location.href = \"/\";\n  }\n\n  return (\n    <>\n      <AccountCard acc={acc} />\n\n      <section className=\"divide-y divide-line rounded-3xl bg-surface ring-1 ring-line\">\n        <div className=\"flex gap-3 p-5\">\n          <ShieldCheck size={18} className=\"mt-0.5 shrink-0 text-forest\" />\n          <div>\n            <p className=\"font-semibold\">Your privacy</p>\n            <p className=\"mt-1 text-sm text-ink-soft\">\n              {signedIn\n                ? \"Your check-ins, sleep, water and notes are saved privately in your account. Only you can see them, not even Kayani staff.\"\n                : \"Your check-ins, sleep, water and notes stay on this phone.\"}{\" \"}\n              We never use them for adverts and never ask for intimate photos.\n            </p>\n          </div>\n        </div>\n        <button onClick={download} className=\"flex w-full items-center gap-3 p-5 text-left\">\n          <Download size={18} className=\"shrink-0 text-forest\" />\n          <span className=\"flex-1 font-semibold\">Download my data</span>\n          <ChevronRight size={16} className=\"text-ink-soft\" />\n        </button>\n        <button onClick={() => setConfirm(true)} className=\"flex w-full items-center gap-3 p-5 text-left text-red-700\">\n          <Trash2 size={18} className=\"shrink-0\" />\n          <span className=\"flex-1 font-semibold\">Delete all my data</span>\n          <ChevronRight size={16} />\n        </button>\n      </section>\n\n      <section className=\"divide-y divide-line rounded-3xl bg-surface ring-1 ring-line\">\n        <Link href=\"/social/c/tool-doctor-check\" className=\"flex items-center gap-3 p-5\">\n          <Stethoscope size={18} className=\"shrink-0 text-forest\" />\n          <span className=\"flex-1\">\n            <span className=\"block font-semibold\">Should I see a doctor?</span>\n            <span className=\"block text-xs text-ink-soft\">A quick check of signs that need a professional.</span>\n          </span>\n          <ChevronRight size={16} className=\"text-ink-soft\" />\n        </Link>\n        <p className=\"p-5 text-xs leading-relaxed text-ink-soft\">\n          Men&apos;s Social gives general education, not medical advice. It doesn&apos;t diagnose or treat any condition. If\n          something worries you, or symptoms last or get worse, please see a qualified health professional.\n        </p>\n      </section>\n\n      <Sheet open={confirm} onClose={() => setConfirm(false)} title=\"Delete everything?\">\n        <p className=\"text-sm text-ink-soft\">\n          This removes your points, badges, check-ins, sleep and water records, saved guides and posts\n          {signedIn ? \" from this phone and from your account (your login stays)\" : \" from this phone\"}. It can&apos;t be undone.\n        </p>\n        <div className=\"mt-4 grid grid-cols-2 gap-2\">\n          <button onClick={() => setConfirm(false)} className=\"rounded-full py-3 text-sm font-semibold ring-1 ring-line\">\n            Keep my data\n          </button>\n          <button onClick={removeAll} className=\"rounded-full bg-red-700 py-3 text-sm font-semibold text-white\">\n            Delete\n          </button>\n        </div>\n      </Sheet>\n    </>\n  );\n}\n",
  "src/lib/tabs.test.ts": "import { describe, expect, it } from \"vitest\";\nimport { isTabRoot, stripPosition, tabFor } from \"./tabs\";\n\ndescribe(\"tabs\", () => {\n  it(\"knows which tab a page belongs to\", () => {\n    expect(tabFor(\"/social/c/abc\")).toBe(0);\n    expect(tabFor(\"/learn/x\")).toBe(1);\n    expect(tabFor(\"/account\")).toBe(2);\n    expect(tabFor(\"/studio\")).toBe(-1);\n  });\n  it(\"only the main page of each tab sits in the sliding strip\", () => {\n    expect(isTabRoot(\"/man\")).toBe(true);\n    expect(isTabRoot(\"/social/c/abc\")).toBe(false);\n  });\n  it(\"shares the strip position with the tab bar\", () => {\n    const seen: number[] = [];\n    const off = stripPosition.subscribe((p) => {\n      seen.push(p);\n    });\n    stripPosition.set(1.5);\n    off();\n    stripPosition.set(2);\n    expect(seen).toEqual([1.5]);\n    expect(stripPosition.get()).toBe(2);\n  });\n});\n",
  "src/lib/tabs.ts": "// The three main tabs, in order. Used by the tab pager and the tab bar.\n\nexport const TAB_PATHS = [\"/social\", \"/man\", \"/me\"] as const;\n\n/** Which tab a page belongs to (for highlighting the tab bar). */\nexport function tabFor(pathname: string): number {\n  if (pathname.startsWith(\"/social\")) return 0;\n  if (pathname.startsWith(\"/man\") || pathname.startsWith(\"/learn\")) return 1;\n  if (pathname.startsWith(\"/me\") || pathname.startsWith(\"/account\")) return 2;\n  return -1;\n}\n\n/** The main page of a tab (shown in the sliding strip). Anything else opens on top of it. */\nexport function isTabRoot(pathname: string): boolean {\n  return (TAB_PATHS as readonly string[]).includes(pathname);\n}\n\n\n/**\n * Where the sliding strip of tabs is right now (0–2, fractions while moving).\n * The pager writes it; the Liquid Glass tab bar reads it every frame. No React re-renders involved.\n */\nlet stripPos = 0;\nconst stripListeners = new Set<(pos: number, byFinger: boolean) => void>();\nexport const stripPosition = {\n  get: () => stripPos,\n  /** byFinger: true while he's swiping the pages (the glass then follows the finger exactly). */\n  set(pos: number, byFinger = false) {\n    stripPos = pos;\n    stripListeners.forEach((l) => l(pos, byFinger));\n  },\n  subscribe(cb: (pos: number, byFinger: boolean) => void) {\n    stripListeners.add(cb);\n    return () => {\n      stripListeners.delete(cb);\n    };\n  },\n};\n"
};

for (const [path, content] of Object.entries(files)) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
  console.log("  wrote", path);
}
console.log("\nDone: " + Object.keys(files).length + " files. Next: npm test, then npx next dev --turbopack, then open http://localhost:3000");
